        return 0 <= x < w and 0 <= y < h

    def parse_cells(key):
        out = []
        for p in (observation.get(key) or []):
            if p and len(p) >= 2:
                try:
                    x, y = int(p[0]), int(p[1])
                except Exception:
                    continue
                if inb(x, y) and (x, y) not in obstacles:
                    out.append((x, y))
        return out

